const fields=new Map();for(const topic of RESEARCH_TOPICS){if(!fields.has(topic.field))fields.set(topic.field,[]);fields.get(topic.field).push(topic);}
export function chooseTopic(state,projectId=state.project?.id??1){
 const all=fields.get(state.professorProfile?.fieldId);if(!all?.length)return null;const pool=state.professorProfile.labMode==='dry'?all.filter(t=>!/실험|합성|시료|제조|제작|배양|촉매|측정 장치/.test(t.title)||/계산|모델|이론|시뮬|전산|데이터|알고리즘|통계|자료/.test(t.title)):all;if(!pool.length)return null;
 // Cosmetic/content RNG never consumes the simulation seed. Step through the pool without repeats.
 const seed=state.creationSeed??state.seed,offset=(Math.imul(seed^Number(state.professorProfile.fieldId),2654435761)>>>0)%pool.length;
 return pool[(offset+projectId-1)%pool.length];
}
const byId=new Map(RESEARCH_TOPICS.map(t=>[t.id,t]));
export const topicById=id=>byId.get(id)??null;
export const validTopicId=id=>byId.has(id);
